using System;using System.Linq;using System.Collections;using System.Collections.Generic;using System.Reflection;using System.Runtime.Serialization;using BeamScheduleFormatter;
public class FakeWorksApp {public int Calculations;public void CalculateFull(){Calculations++;}}
public class FakeWorksBook {public readonly FakeWorksSheets Worksheets=new FakeWorksSheets();public int Saves;public void Save(){Saves++;}}
public class FakeWorksSheets:IEnumerable {
 readonly List<FakeWorksSheet> list=new List<FakeWorksSheet>();public FakeWorksSheet Add(){var s=new FakeWorksSheet();list.Add(s);return s;}public FakeWorksSheet this[string name]{get{return list.First(x=>x.Name==name);}}public IEnumerator GetEnumerator(){return list.GetEnumerator();}}
public class FakeWorksSheet {
 public string Name{get;set;}public int Visible{get;set;}public readonly Dictionary<string,object> Values=new Dictionary<string,object>();public readonly Dictionary<string,string> Formats=new Dictionary<string,string>();public FakeWorksRanges Range{get{return new FakeWorksRanges(this);}}public FakeWorksCells Cells{get{return new FakeWorksCells(this);}}public FakeWorksRange UsedRange{get{return new FakeWorksRange(this,1,1,10000,52);}}public void Activate(){}
 public object At(int row,int col){object v;return Values.TryGetValue(row+":"+col,out v)?v:null;}}
public class FakeWorksCells {readonly FakeWorksSheet s;public FakeWorksCells(FakeWorksSheet sheet){s=sheet;}public FakeWorksRange this[int row,int col]{get{return new FakeWorksRange(s,row,col,row,col);}}}
public class FakeWorksRanges {
 readonly FakeWorksSheet s;public FakeWorksRanges(FakeWorksSheet sheet){s=sheet;}static int[] Parse(string cell){int c=0,i=0;while(i<cell.Length&&char.IsLetter(cell[i])){c=c*26+char.ToUpperInvariant(cell[i])-64;i++;}return new[]{int.Parse(cell.Substring(i)),c};}
 public FakeWorksRange this[string text]{get{var bits=text.Split(':');var a=Parse(bits[0]);var b=Parse(bits.Length>1?bits[1]:bits[0]);return new FakeWorksRange(s,a[0],a[1],b[0],b[1]);}}
 public FakeWorksRange this[object a,object b]{get{var x=(FakeWorksRange)a;var y=(FakeWorksRange)b;return new FakeWorksRange(s,x.R1,x.C1,y.R2,y.C2);}}}
public class FakeWorksFont {public bool Bold{get;set;}}
public class FakeWorksRange {
 readonly FakeWorksSheet s;public readonly int R1,C1,R2,C2;public FakeWorksRange(FakeWorksSheet sheet,int r1,int c1,int r2,int c2){s=sheet;R1=r1;C1=c1;R2=r2;C2=c2;}public FakeWorksFont Font{get{return new FakeWorksFont();}}public FakeWorksRange Columns{get{return this;}}public void AutoFit(){}public string NumberFormat{set{for(int r=R1;r<=R2;r++)for(int c=C1;c<=C2;c++)s.Formats[r+":"+c]=value;}}
 public object Value2{get{return s.At(R1,C1);}set{var array=value as object[,];for(int r=R1;r<=R2;r++)for(int c=C1;c<=C2;c++)s.Values[r+":"+c]=array==null?value:array[r-R1,c-C1];}}
 public void ClearContents(){foreach(string key in s.Values.Keys.ToList()){var bits=key.Split(':');int r=int.Parse(bits[0]),c=int.Parse(bits[1]);if(r>=R1&&r<=R2&&c>=C1&&c<=C2)s.Values.Remove(key);}}
}
class WorksWorkbookWriterTests {
 static int checks;static void Check(bool v,string m){if(!v)throw new Exception(m);checks++;}
 static ExcelLiveLink Link(FakeWorksBook book,FakeWorksApp app){var link=(ExcelLiveLink)FormatterServices.GetUninitializedObject(typeof(ExcelLiveLink));typeof(ExcelLiveLink).GetField("book",BindingFlags.NonPublic|BindingFlags.Instance).SetValue(link,book);typeof(ExcelLiveLink).GetField("app",BindingFlags.NonPublic|BindingFlags.Instance).SetValue(link,app);return link;}
 static void Main(){var book=new FakeWorksBook();var app=new FakeWorksApp();var custom=book.Worksheets.Add();custom.Name="User BOQ";custom.Range["A1"].Value2="=1+1";var owned=book.Worksheets.Add();owned.Name="POW Summary";owned.Range["AA1"].Value2="DTCEProgramOfWorksV1:POW Summary";owned.Range["E5"].Value2="=B5*2";owned.Range["A40"].Value2="Keep this custom note";var v=new Dictionary<string,double>();foreach(var m in WorksSummaryLayout.Map)v[m[0]]=1.25;var data=new List<object[]>{new object[]{"=UNTRUSTED()",2.5}};var tables=new List<WorksExcelTable>{WorksSummaryLayout.Build(v),WorksSummaryLayout.CellMap(),new WorksExcelTable("POW Finishes",new[]{"Description","Area m2"},data),FinishTypeCatalog.Table(new List<FinishTypeTotal>{new FinishTypeTotal{Key=FinishTypeRegistry.Key(FinishTypeCatalog.Names[4]),Name=FinishTypeCatalog.Names[4],Area=31}})};const string xml="<ProgramOfWorks version='3'><Wood/><Aluminum/><Walls/></ProgramOfWorks>";
 using(var link=Link(book,app)){link.UpdateWorks(tables,xml);Check(owned.Name=="DTCE Tool Kit - POW","Old owned summary not renamed");Check(Convert.ToDouble(owned.Range["E40"].Value2)==31&&Convert.ToDouble(owned.Range["E36"].Value2)==0,"Preset fixed block not written");Check(Convert.ToDouble(owned.Range["B5"].Value2)==1.25,"B5 shifted");Check(Convert.ToString(owned.Range["E5"].Value2)=="=B5*2"&&Convert.ToString(owned.Range["A40"].Value2)=="Keep this custom note","Custom summary cells overwritten");Check(Convert.ToString(custom.Range["A1"].Value2)=="=1+1","Unrelated worksheet overwritten");Check(book.Worksheets["POW Finishes"].Formats["2:1"]=="@","Description not stored as literal text");Check(book.Worksheets["POW Finishes"].Formats["2:2"]=="0.00","Numeric area format changed");Check(link.ReadWorksProject()==xml,"Embedded project round trip failed");Check(book.Worksheets["DTCE_POW_Project"].Visible==2,"Project sheet not hidden");v["Grade40"]=15;tables[0]=WorksSummaryLayout.Build(v);link.UpdateWorks(tables,xml);Check(Convert.ToDouble(owned.Range["B5"].Value2)==15&&Convert.ToDouble(owned.Range["B6"].Value2)==1.25,"Second update moved cells");Check(book.Saves==2&&app.Calculations==2,"Workbook not recalculated/saved");}
 var collisionBook=new FakeWorksBook();var reserved=collisionBook.Worksheets.Add();reserved.Name="POW Finishes";reserved.Range["A1"].Value2="My existing sheet";using(var link=Link(collisionBook,new FakeWorksApp())){bool rejected=false;try{link.UpdateWorks(tables,xml);}catch{rejected=true;}Check(rejected&&collisionBook.Saves==0&&Convert.ToString(reserved.Range["A1"].Value2)=="My existing sheet","Unowned sheet collision overwrote data");}var blockedBook=new FakeWorksBook();var blocked=blockedBook.Worksheets.Add();blocked.Name=WorksSummaryLayout.Sheet;blocked.Range["AA1"].Value2="DTCEProgramOfWorksV1:"+WorksSummaryLayout.Sheet;blocked.Range["E40"].Value2="Custom data";using(var link=Link(blockedBook,new FakeWorksApp())){bool rejected=false;try{link.UpdateWorks(tables,xml);}catch{rejected=true;}Check(rejected&&blockedBook.Saves==0&&Convert.ToString(blocked.Range["E40"].Value2)=="Custom data","New preset block overwrote custom data");}var footingCollision=new FakeWorksBook();var footSheet=footingCollision.Worksheets.Add();footSheet.Name=WorksSummaryLayout.Sheet;footSheet.Range["AA1"].Value2="DTCEProgramOfWorksV1:"+WorksSummaryLayout.Sheet;footSheet.Range["B34"].Value2="Keep my existing data";using(var link=Link(footingCollision,new FakeWorksApp())){bool rejected=false;try{link.UpdateWorks(tables,xml);}catch{rejected=true;}Check(rejected&&footingCollision.Saves==0&&Convert.ToString(footSheet.Range["B34"].Value2)=="Keep my existing data","New footing cells overwrote custom content");}Console.WriteLine("PASS: "+checks+" workbook-writer checks using an Excel object-model fake: fixed addresses, custom-cell preservation, text safety, project embedding and ownership preflight.");}
}
